css:
.loader {
  display: flex;
  gap: 2px;
  width: 54px;
  height: 40px;
}
.loader i {
  width: 12px;
  height: 40px;
  border: 1px solid #c7d2fe;
  border-radius: 0 0 3px 3px;
  box-sizing: border-box;
  background: #eef2ff;
  transform-origin: top center;
  animation: press 1.2s ease-in-out infinite;
}
.loader i:nth-child(1) { animation-delay: 0s; }
.loader i:nth-child(2) { animation-delay: 0.15s; }
.loader i:nth-child(3) { animation-delay: 0.3s; }
.loader i:nth-child(4) { animation-delay: 0.45s; }
@keyframes press {
  0%, 100% { transform: rotateX(0deg); background: #eef2ff; }
  15% { transform: rotateX(-22deg); background: #6366f1; }
}
